export interface ConnectorConfig {
  discordWebhookId: string
  discordWebhookToken: string
  fetch?: typeof fetch
}

export interface AirtableRecordPayload {
  id: string
  fields: Record<string, unknown>
  createdTime: string
}

export interface DiscordWebhookResult {
  success: boolean
}

export async function handle(
  payload: AirtableRecordPayload,
  config: ConnectorConfig
): Promise<DiscordWebhookResult> {
  if (!payload.id) throw new Error('Missing required field: id')
  if (!payload.fields || typeof payload.fields !== 'object') throw new Error('Missing required field: fields')
  if (!payload.createdTime) throw new Error('Missing required field: createdTime')
  if (!config.discordWebhookId) throw new Error('Missing config: discordWebhookId')
  if (!config.discordWebhookToken) throw new Error('Missing config: discordWebhookToken')

  const fetchImpl = config.fetch ?? fetch

  const fieldLines = Object.entries(payload.fields)
    .map(([key, value]) => `${key}: ${String(value)}`)
    .join('\n')

  const content = `New Airtable record: ${payload.id}\n${fieldLines}`

  const discordPayload = {
    content,
    embeds: [
      {
        title: 'New Record Created',
        description: 'A new record has been added to your Airtable base',
        color: 3066993,
        fields: [
          { name: 'Record ID', value: payload.id, inline: true },
          { name: 'Created', value: payload.createdTime, inline: true }
        ],
        timestamp: payload.createdTime
      }
    ]
  }

  const url = `https://discord.com/api/webhooks/${config.discordWebhookId}/${config.discordWebhookToken}`

  const response = await fetchImpl(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(discordPayload)
  })

  if (!response.ok) {
    throw new Error(`Discord webhook failed: ${response.status} ${response.statusText} at ${url}`)
  }

  return { success: true }
}

